  "definitions": [
    {
      "term": ["class"],
      "definition_text": ["A class in Java is a blueprint that groups related functions (methods) together."],
      "context": {
        "is_null": false,
        "value": ["Q0002"]
      }
    },
    {
      "term": ["method"],
      "definition_text": ["A method is a function that is part of a class."],
      "context": {
        "is_null": false,
        "value": ["Q0009"]
      }
    },
    {
      "term": ["access modifier"],
      "definition_text": ["An access modifier is a special keyword that determines whether other classes and methods can access a given class or method."],
      "context": {
        "is_null": false,
        "value": ["Q0012"]
      }
    }
  ],
  "explanations": [],
  "examples": [],
  "facts": [
    {
      "fact_text": ["Each section in a supermarket contains related products."],
      "fact_type": {
        "is_null": false,
        "value": ["Q0001"]
      }
    },
    {
      "fact_text": ["A Java class contains related functions."],
      "fact_type": {
        "is_null": false,
        "value": ["Q0002"]
      }
    },
    {
      "fact_text": ["Every Java program must have at least one class that contains the main function."],
      "fact_type": {
        "is_null": false,
        "value": ["Q0003"]
      }
    },
    {
      "fact_text": ["The name of the class that contains the main function is \"main\"."],
      "fact_type": {
        "is_null": false,
        "value": ["Q0005"]
      }
    },
    {
      "fact_text": ["A class is defined with the keyword \"class\", a descriptive name, and a pair of curly braces."],
      "fact_type": {
        "is_null": false,
        "value": ["Q0007"]
      }
    },
    {
      "fact_text": ["Methods are defined inside the curly braces of a class."],
      "fact_type": {
        "is_null": false,
        "value": ["Q0008"]
      }
    },
    {
      "fact_text": ["In Java, classes and methods typically have an access modifier such as public or private."],
      "fact_type": {
        "is_null": false,
        "value": ["Q0011", "Q0013"]
      }
    },
    {
      "fact_text": ["The public access modifier is most commonly used and is placed before class and method declarations."],
      "fact_type": {
        "is_null": false,
        "value": ["Q0014"]
      }
    }
  ],
  "formulas": [],
  "procedures": [],
  "relationships": [],
